// Diagonal stripes — angle set by #define, density slider, invert checkbox.
#define STRIPE_ANGLE 45.0   // degrees

uniform float uDensity; // @param 12.0 1 80
uniform bool  uInvert;  // @param false

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float a = radians(STRIPE_ANGLE);
  float d = dot(p, vec2(cos(a), sin(a))) * uDensity;
  float f = fract(d);
  float w = fwidth(d) * 0.75;
  // anti-aliased 50% duty stripe
  float s = smoothstep(0.5 - w, 0.5 + w, f) - smoothstep(1.0 - w, 1.0 + w, f) + smoothstep(-w, w, f) - 1.0;
  s = clamp(s, 0.0, 1.0);
  if (uInvert) s = 1.0 - s;
  vec3 col = vec3(s);
  fragColor = vec4(col, 1.0);
}
